// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Cis) predicate.Cis {
	return predicate.Cis(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Cis) predicate.Cis {
	return predicate.Cis(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Cis) predicate.Cis {
	return predicate.Cis(sql.NotPredicates(p))
}
